INSERT INTO `job_interview` VALUES (1,'Technical Interview','A technical interview assesses a candidate\'s skills through coding challenges, problem-solving, and discussions on technical concepts, focusing on their expertise in the role.','2025-08-05 15:36:37','2025-08-05 15:36:37'),(2,'Psychological Interview','A psychological interview evaluates behavioral, emotional, and interpersonal skills to understand a candidate\'s personality traits and reactions under certain circumstances.','2025-08-05 15:36:37','2025-08-05 15:36:37'),(3,'Behavioral Interview','A behavioral interview evaluates how candidates have handled past situations and challenges, providing insights into their personality, behavior, and problem-solving approach.','2025-08-05 15:36:37','2025-08-05 15:36:37'),(4,'Management Interview','A management interview focuses on leadership qualities, decision-making skills, and the ability to inspire and manage a team.','2025-08-05 15:36:37','2025-08-05 15:36:37'),(5,'Cultural Fit Interview','A cultural fit interview assesses a candidate\'s alignment with the company\'s values, work environment, and overall culture.','2025-08-05 15:36:38','2025-08-05 15:36:38'),(6,'Test Interview','Sample Interview.','2025-08-05 15:36:38','2025-08-05 15:36:38');
/*!40000 ALTER TABLE `job_interview` ENABLE KEYS */;
UNLOCK TABLES;

